def is_permutation_polynomial(a3, a1, p):
    """Checks if P(x) = a3*x^3 + a1*x is a permutation polynomial modulo p."""
    residues = set()
    for x in range(p):
        # Calculate P(x) = a3*x^3 + a1*x mod p
        px = (a3 * pow(x, 3, p) + a1 * x) % p
        residues.add(px)
    return len(residues) == p

