def is_permutation_polynomial(coeffs, p):
    seen = [False] * p
    for x in range(p):
        val = (coeffs[0]*x**3 + coeffs[1]*x**2 + coeffs[2]*x + coeffs[3]) % p
        if seen[val]:
            return False
        seen[val] = True
    return True

def count_polynomials():
    p_list = [3, 11, 61]
    # Cases for (a2, a0)
    possible_cases = [
        (0, 0),
        (671, 1342),
        (1342, 671)
    ]

    total_solutions = 0
    for a2, a0 in possible_cases:
        count_p = []
        for p in p_list:
            a2_p = a2 % p
            a0_p = a0 % p
            count_in_p = 0
            for a3_p in range(p):
                for a1_p in range(p):
                    if is_permutation_polynomial([a3_p, a2_p, a1_p, a0_p], p):
                        count_in_p += 1
            count_p.append(count_in_p)
        total_solutions += count_p[0] * count_p[1] * count_p[2]

    print(f"Total solutions: {total_solutions}")

